INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1036636', 'Battle of Hwangsanbeol', 'The Battle of Hwangsanbeol (Korean: 황산벌 전투; Hanja: 黃山伐戰鬪) took place between the forces of Silla and Baekje in Hwangsanbeol (currently Nonsan) in 660. By the time King Muyeol was able to gain the support of Emperor Gaozong of Tang China to conquer Baekje.', 660, NULL, NULL, NULL, NULL, NULL, 'year', '660', 45, 'https://en.wikipedia.org/wiki/Battle_of_Hwangsanbeol'),
  ('Q490792', 'Sambyeolcho Rebellion', 'The Sambyeolcho Rebellion (1270–1273) was a Korean rebellion against the pro-Mongol Goryeo dynasty that happened near the end of the Mongol invasions of Korea. It was suppressed by Goryeo and the Mongol Yuan dynasty.', 1270, 6, NULL, 1273, NULL, NULL, 'month', 'June 1270 – 1273', 43, 'https://en.wikipedia.org/wiki/Sambyeolcho_Rebellion'),
  ('Q482970', 'Battle of Sacheon', 'The Battle of Sacheon was a naval engagement on May 29, 1592 (Gregorian: July 8, 1592) during the Imjin War (1592–98). It occurred at Sacheon where Yi Sunsin''s fleet managed to destroy 13 large Japanese ships.', 1592, 7, 8, NULL, NULL, NULL, 'day', '8 July 1592', 48, 'https://en.wikipedia.org/wiki/Battle_of_Sacheon_(1592)'),
  ('Q484256', 'Battle of Okpo', 'The Battle of Okpo was a military engagement which took place during the Japanese invasions of Korea (1592–98), also known as the Imjin War. Korean commanders Yi Sun-sin and Wŏn Kyun''s fleet destroyed a group of anchored Japanese transport ships.', 1592, 5, 8, NULL, NULL, NULL, 'day', '8 May 1592', 52, 'https://en.wikipedia.org/wiki/Battle_of_Okpo'),
  ('Q486979', 'Battle of Ch''ungju', 'The Battle of Chungju or the Battle of Tangeumdae was the last battle of the Chungju Campaign fought between the Koreans and Japanese during the Japanese invasion of Korea in 1592. Chungju is located just south of the Han River and Seoul, Korea''s capital.', 1592, 4, 28, NULL, NULL, NULL, 'day', '28 April 1592', 45, 'https://en.wikipedia.org/wiki/Battle_of_Chungju'),
  ('Q487332', 'Battle of Hansan Island', 'The Battle of Hansan Island (Korean: 한산도 대첩) and the following engagement at Angolpo took place on 15 August 1592. In two naval encounters, Korean Admiral Yi Sun-sin''s fleet managed to destroy roughly 100 Japanese ships and halted Japanese naval operations along the southern coast.', 1592, 8, 15, NULL, NULL, NULL, 'day', '15 August 1592', 51, 'https://en.wikipedia.org/wiki/Battle_of_Hansan_Island'),
  ('Q497046', 'Siege of Busan', 'The siege of Busanjin (Korean: 부산진 전투; Hanja: 釜山鎭戰鬪) was a battle fought at Busan on 24 May 1592, between Japanese and Korean forces. The attacks on Busan and the neighboring fort of Dadaejin were the first battles of the Japanese invasions of Korea (1592–98).', 1592, 5, 24, 1592, 5, 25, 'day', '24 May 1592 – 25 May 1592', 52, 'https://en.wikipedia.org/wiki/Siege_of_Busanjin'),
  ('Q497348', 'Siege of Dongnae', 'The siege of Dongnae (Korean: 동래성 전투) was a siege that occurred on May 25, 1592 (Korean calendar: April 15, 1592) during the 1592–1598 Japanese invasions of Korea. It resulted in the capture by Japanese forces of Dongnaeeupseong, a mountain fortress on the way to Hanseong (Seoul).', 1592, 4, 15, NULL, NULL, NULL, 'day', '15 April 1592', 48, 'https://en.wikipedia.org/wiki/Siege_of_Dongnae'),
  ('Q626291', 'Battle of Dangpo', 'The Battle of Dangpo (Korean: 당포 해전; Hanja: 唐浦海戰) was a naval engagement during the Japanese invasions of Korea (1592–1598) on 10 July that resulted in Yi Sun-sin''s victory.', 1592, 7, 9, NULL, NULL, NULL, 'day', '9 July 1592', 43, 'https://en.wikipedia.org/wiki/Battle_of_Dangpo_(1592)'),
  ('Q1047445', 'Battle of Dadaejin', 'The Battle of Dadaejin and the Siege of Busan were the first battles of the Japanese invasions of Korea (1592–1598) and occurred simultaneously on April 13–14, 1592 (Gregorian: May 23–24, 1592).', 1592, 5, 24, NULL, NULL, NULL, 'day', '24 May 1592', 45, 'https://en.wikipedia.org/wiki/Battle_of_Dadaejin'),
  ('Q4871272', 'Battle of Imjin River', 'The Battle of Imjin River (Japanese: 臨津江の戦い) was a battle during the 1592 Japanese invasion of Korea. Kim Myŏngwŏn''s northern defense was defeated and the Japanese were able to cross over and invade northern Korea.', 1592, 7, 7, NULL, NULL, NULL, 'day', '7 July 1592', 47, 'https://en.wikipedia.org/wiki/Battle_of_Imjin_River_(1592)'),
  ('Q279611', 'Siege of Haengju', 'The Battle of Haengju took place on 14 March 1593 during the 1592–1598 Japanese invasion of Korea. The Japanese attack failed to overcome the fortress Haengjusanseong.', 1593, 3, 14, NULL, NULL, NULL, 'day', '14 March 1593', 48, 'https://en.wikipedia.org/wiki/Battle_of_Haengju'),
  ('Q385677', 'Battle of Myeongnyang', 'The Battle of Myeongnyang was fought on October 26, 1597 between the Joseon Navy led by Admiral Yi Sun-sin and the Japanese navy in the Myeongnyang Strait, near Jindo Island, off the southwest corner of the Korean Peninsula. With only 13 ships remaining from Admiral Wŏn Kyun''s disastrous defeat at the Battle of Chilcheollyang, Admiral Yi held the strait as a "last stand" battle against the Japanese navy, who were sailing to support their land army''s advance towards the Joseon capital of Hanyang (modern-day Seoul).', 1597, 10, 26, NULL, NULL, NULL, 'day', '26 October 1597', 57, 'https://en.wikipedia.org/wiki/Battle_of_Myeongnyang'),
  ('Q483088', 'Battle of Chilcheollyang', 'The Battle of Chilcheollyang was a naval engagement fought during the night of 28 August 1597, as part of the Imjin War. In this battle, the Japanese fleet decisively defeated the Joseon navy, destroying nearly the entire Korean fleet.', 1597, 8, 27, NULL, NULL, NULL, 'day', '27 August 1597', 48, 'https://en.wikipedia.org/wiki/Battle_of_Chilcheollyang'),
  ('Q484271', 'Battle of Noryang', 'The Battle of Noryang, the last major battle of the Japanese invasions of Korea (1592–1598), was fought between the Japanese navy and the combined fleets of the Joseon Kingdom and the Ming dynasty. It took place in the early morning of 16 December (19 November in the Lunar calendar) 1598 and ended past dawn.', 1598, 12, 16, NULL, NULL, NULL, 'day', '16 December 1598', 56, 'https://en.wikipedia.org/wiki/Battle_of_Noryang'),
  ('Q490935', 'Siege of Ulsan', 'The siege of Ulsan (Korean: 울산성 전투; Hanja: 蔚山城戰鬪; MR: Ulsansŏng chŏnt''u) was an unsuccessful Ming-Joseon attempt to capture Ulsan from the Japanese. The siege lasted from 26 January to 19 February 1598.', 1598, NULL, NULL, 1598, 1, 4, 'year', '1598', 45, 'https://en.wikipedia.org/wiki/Siege_of_Ulsan'),
  ('Q496905', 'Ganghwa Island incident', 'The Ganghwa Island incident or the Japanese Battle of Ganghwa (Korean: 운요호 사건 [雲揚號事件] Unyo-ho sageon meaning "Un''yō incident"; Japanese: 江華島事件 Kōka-tō jiken) was an armed clash between the Joseon dynasty of Korea and Japan which occurred in the vicinity of Ganghwa Island on September 20, 1875.', 1875, 9, 20, NULL, NULL, NULL, 'day', '20 September 1875', 53, 'https://en.wikipedia.org/wiki/Ganghwa_Island_incident'),
  ('Q701890', 'Battle of Pungdo', 'The Battle of Pungdo (Japanese: 豊島沖海戦, romanized: Hoto-oki kaisen) was the first naval battle of the First Sino-Japanese War. It took place on 25 July 1894 off Asan, Chungcheongnam-do, Korea, between cruisers of the Imperial Japanese Navy and components of the Chinese Beiyang Fleet.', 1894, 7, 25, NULL, NULL, NULL, 'day', '25 July 1894', 52, 'https://en.wikipedia.org/wiki/Battle_of_Pungdo'),
  ('Q702150', 'Battle off Ulsan', 'The naval Battle off Ulsan (Japanese: 蔚山沖海戦 Urusan''oki kaisen; Russian: Бой в Корейском проливе, Boi v Koreiskom prolive), also known as the Battle of the Japanese Sea or Battle of the Korean Strait, took place on 14 August 1904 between cruiser squadrons of the Imperial Russian Navy and the Imperial Japanese Navy during the Russo-Japanese War, four days after the Battle of the Yellow Sea.', 1904, 8, 14, NULL, NULL, NULL, 'day', '14 August 1904', 52, 'https://en.wikipedia.org/wiki/Battle_off_Ulsan'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q482979', 'Battle of Pusan Perimeter', 'The Battle of the Pusan Perimeter, known in Korean as the Battle of the Naktong River Defense Line (Korean: 낙동강 방어선 전투), was a large-scale battle between United Nations Command (UN) and North Korean forces lasting from August 4 to September 18, 1950. It was one of the first major engagements of the Korean War.', 1950, 8, 4, 1950, 9, 18, 'day', '4 August 1950 – 18 September 1950', 57, 'https://en.wikipedia.org/wiki/Battle_of_the_Pusan_Perimeter'),
  ('Q483039', 'Battle of Inchon', 'The Battle of Inchon (Korean: 인천 상륙 작전; Hanja: 仁川上陸作戰; MR: Inch''ŏn sangnyuk chakchŏn), also called the Inchon landings, was an amphibious invasion and battle of the Korean War that resulted in a decisive victory and strategic reversal in favor of the United Nations Command. The operation involved some 75,000 troops and 261 naval vessels and led to the recapture of the South Korean capital of Seoul two weeks later.', 1950, 9, 15, 1950, 9, 19, 'day', '15 September 1950 – 19 September 1950', 67, 'https://en.wikipedia.org/wiki/Battle_of_Inchon'),
  ('Q484494', 'Battle of Osan', 'The Battle of Osan (Korean: 오산 전투) was the first engagement between the United States and North Korea during the Korean War. On July 5, 1950, Task Force Smith, an American task force of 540 infantry supported by an artillery battery, was moved to Osan, south of Seoul, the capital of South Korea, and was ordered to fight as a rearguard to delay the advancing North Korean forces while more US troops arrived to form a stronger defensive line to the south.', 1950, 7, 4, NULL, NULL, NULL, 'day', '4 July 1950', 52, 'https://en.wikipedia.org/wiki/Battle_of_Osan'),
  ('Q492880', 'Battle of Taejon', 'The Battle of Taejon (16–20 July 1950) was an early battle of the Korean War, between U.S. and North Korean forces. Forces of the United States Army attempted to defend the headquarters of the 24th Infantry Division.', 1950, 7, 14, 1950, 7, 21, 'day', '14 July 1950 – 21 July 1950', 53, 'https://en.wikipedia.org/wiki/Battle_of_Taejon'),
  ('Q493131', 'Battle of Pyongtaek', 'The Battle of Pyongtaek was the second engagement between United States and North Korean forces during the Korean War, occurring on July 6, 1950, in the village of Pyongtaek in western South Korea. The fight ended in a North Korean victory following unsuccessful attempts by American forces to inflict significant damage or delays on advancing North Korean units, despite several opportunities to do so.', 1950, 7, 6, NULL, NULL, NULL, 'day', '6 July 1950', 41, 'https://en.wikipedia.org/wiki/Battle_of_Pyongtaek'),
  ('Q493922', 'Third Battle of Seoul', 'The Third Battle of Seoul was a battle of the Korean War, which took place from December 31, 1950, to January 7, 1951, around the South Korean capital of Seoul. It is also known as the Chinese New Year''s Offensive, the January–Fourth Retreat (Korean: 1·4 후퇴) or the Third Phase Campaign Western Sector (Chinese: 第三次战役西线; pinyin: Dì Sān Cì Zhàn Yì Xī Xiàn).', 1950, 12, 31, 1951, 1, 7, 'day', '31 December 1950 – 7 January 1951', 45, 'https://en.wikipedia.org/wiki/Third_Battle_of_Seoul'),
  ('Q494043', 'Hill 303 massacre', 'The Hill 303 massacre (Korean: 303 고지 학살 사건) was a massacre that took place during the opening days of the Korean War on August 17, 1950, on a hill above Waegwan, Republic of Korea. Forty-one United States Army (US) prisoners of war were murdered by troops of the North Korean People''s Army (KPA) during one of the engagements of the Battle of Pusan Perimeter.', 1950, 8, 17, NULL, NULL, NULL, 'day', '17 August 1950', 51, 'https://en.wikipedia.org/wiki/Hill_303_massacre'),
  ('Q495446', 'No Gun Ri Massacre', 'The No Gun Ri massacre was a mass killing of South Korean civilian refugees by United States military air and ground forces near the village of Nogeun-ri (노근리) in central South Korea from July 26 to 29, 1950, during the US Army''s retreat in the early phase of the Korean War. In 2005, a South Korean government inquest certified the names of 163 dead or missing and 55 wounded, and added that many other victims'' names were not reported.', 1950, 7, 26, 1950, 7, 29, 'day', '26 July 1950 – 29 July 1950', 58, 'https://en.wikipedia.org/wiki/No_Gun_Ri_massacre'),
  ('Q2888742', 'Battle of Kyongju', 'The Battle of Kyongju was an engagement between United Nations Command (UN) and North Korean forces early in the Korean War from August 31 to September 15, 1950, in the vicinity of Kyongju in South Korea. It was a part of the Battle of Pusan Perimeter, and was one of several large engagements fought simultaneously.', 1950, 8, 27, 1950, 9, 12, 'day', '27 August 1950 – 12 September 1950', 39, 'https://en.wikipedia.org/wiki/Battle_of_Kyongju'),
  ('Q2890901', 'Battle of Nam River', 'The Battle of Nam River was an engagement between the United Nations Command (UN) and North Korean forces early in the Korean War from August 31 to September 19, 1950, in the vicinity of the Nam River and the Naktong River in South Korea. It was a part of the Battle of Pusan Perimeter, and was one of several large engagements fought simultaneously.', 1950, 8, 31, 1950, 9, 19, 'day', '31 August 1950 – 19 September 1950', 45, 'https://en.wikipedia.org/wiki/Battle_of_Nam_River'),
  ('Q4438418', 'Battle of P''ohang-dong', 'The Battle of P''ohang-dong was an engagement between the United Nations Command (UN) and North Korean forces early in the Korean War, with fighting continuing from 5–20 August 1950 around the town of P''ohang-dong, South Korea. It was a part of the Battle of Pusan Perimeter, and was one of several large engagements fought simultaneously.', 1950, 8, 5, 1950, 8, 20, 'day', '5 August 1950 – 20 August 1950', 39, 'https://en.wikipedia.org/wiki/Battle_of_P''ohang-dong'),
  ('Q4870302', 'Battle of Andong', 'The Battle of Andong was a fight between North Korean and South Korean units in late July 1950. It was an early maneuver of the Korean War.', 1950, 7, NULL, NULL, NULL, NULL, 'month', 'July 1950', 41, 'https://en.wikipedia.org/wiki/Battle_of_Andong'),
  ('Q7521988', 'Sinchon Massacre', 'The Sinchon Massacre (Korean: 신천 양민학살 사건; Hanja: 信川良民虐殺事件; lit. ''Sinchon Civilian Massacre'') was a massacre of civilians between 17 October and 7 December 1950, in or near the town of Sinchon (currently part of South Hwanghae Province, North Korea).', 1950, 10, 17, 1950, 12, 7, 'day', '17 October 1950 – 7 December 1950', 41, 'https://en.wikipedia.org/wiki/Sinchon_Massacre'),
  ('Q18016068', 'First Battle of Seoul', 'The First Battle of Seoul was one of the early battles of the Korean War. Following the border engagements at the outbreak of the war, it was fought between the Republic of Korea Armed Forces and the Korean People''s Army of North Korea from 26 to 28 June 1950 across the central region of South Korea, centering on the city of Seoul.', 1950, 6, 25, NULL, NULL, NULL, 'day', '25 June 1950', 52, 'https://en.wikipedia.org/wiki/First_Battle_of_Seoul'),
  ('Q496095', 'Ganghwa massacre', 'The Ganghwa massacre (Korean: 강화 양민학살 사건; Hanja: 江華良民虐殺事件) was a massacre conducted by the South Korean forces, South Korean Police forces and pro-South Korean militiamen, between 6 and 9 January 1951, of 212 to 1,300 unarmed civilians in the Ganghwa county of the Incheon metropolitan city in South Korea. The victims were so-called collaborators with the Korean People''s Army during North Korean occupation.', 1951, 1, 6, NULL, NULL, NULL, 'day', '6 January 1951', 41, 'https://en.wikipedia.org/wiki/Ganghwa_massacre'),
  ('Q713018', 'Battle of Kapyong', 'The Battle of Kapyong (Korean: 가평 전투; MR: Kap''yŏng chŏnt''u; 22–27 April 1951), also known as the Battle of Jiaping (Chinese: 加平战斗; pinyin: Jiāpíng Zhàndòu), was a pivotal engagement fought during the Korean War between United Nations Command (UN) forces—primarily Canadian, Australian, and New Zealand—and the 118th and 60th Divisions of the Chinese People''s Volunteer Army (PVA). The fighting occurred during the Chinese Spring Offensive and saw the 27th British Commonwealth Brigade (27th Brigade) establish blocking positions in the Kapyong Valley, on a key route south to the capital, Seoul.', 1951, 4, 22, 1951, 4, 25, 'day', '22 April 1951 – 25 April 1951', 41, 'https://en.wikipedia.org/wiki/Battle_of_Kapyong'),
  ('Q247253', 'Battle of Khe Sanh', 'The Battle of Khe Sanh (21 January – 9 July 1968) was conducted in the Khe Sanh area of northwestern Quảng Trị Province, Republic of Vietnam (South Vietnam), during the Vietnam War. The main forces defending Khe Sanh Combat Base (KSCB) were a regiment of the United States Marine Corps and a battalion of Army of the Republic of Vietnam (ARVN) troops.', 1968, 1, 21, 1968, 7, 9, 'day', '21 January 1968 – 9 July 1968', 68, 'https://en.wikipedia.org/wiki/Siege_of_Khe_Sanh'),
  ('Q14375588', 'Taeyunkak Hotel Fire', 'The Daeyeonggak Hotel fire was a skyscraper fire in Seoul, South Korea, on 25 December 1971, which killed 164 people and injured 63. It remains the deadliest hotel fire in history.', 1971, 12, 25, NULL, NULL, NULL, 'day', '25 December 1971', 43, 'https://en.wikipedia.org/wiki/Daeyeonggak_Hotel_fire'),
  ('Q458321', 'Korean Air Lines Flight 902', 'Korean Air Lines Flight 902 was a scheduled Korean Air Lines flight from Paris to Seoul via Anchorage. On 20 April 1978, the Soviet air defense shot down the aircraft serving the flight, a Boeing 707, near Murmansk, Soviet Union, after the aircraft violated Soviet airspace.', 1978, 4, 20, NULL, NULL, NULL, 'day', '20 April 1978', 61, 'https://en.wikipedia.org/wiki/Korean_Air_Lines_Flight_902'),
  ('Q623641', 'Coup d''état of December Twelfth', 'The coup d''état of December Twelfth or the 12·12 Military Insurrection (Korean: 12·12 군사 반란; Hanja: 十二十二軍事反亂) was a mutiny which took place on 12 December 1979, in South Korea, where a secret society of military officers known as Hanahoe led by Major General Chun Doo-hwan mutinied against the Chief of Staff of the Republic of Korea Army General Jeong Seung-hwa. The coup led to Chun strengthening his military and political position in South Korea, leading to his outright seizure of power as president in 1980.', 1979, 12, 12, NULL, NULL, NULL, 'day', '12 December 1979', 51, 'https://en.wikipedia.org/wiki/1979_South_Korean_coup_d''%C3%A9tat'),
  ('Q623959', 'Seoul Spring', 'The Seoul Spring (Korean: 서울의 봄) was a period of democratization in South Korea from 26 October 1979 to 17 May 1980. This expression was derived from the Prague Spring of Czechoslovakia in 1968.', 1979, 10, 27, 1980, 5, 17, 'day', '27 October 1979 – 17 May 1980', 41, 'https://en.wikipedia.org/wiki/Seoul_Spring'),
  ('Q174990', 'Gwangju Uprising', 'The Gwangju Uprising, also known in South Korea as the May 18 Democratization Movement (Korean: 5·18 민주화 운동), was a series of student-led demonstrations that took place in Gwangju, South Korea, in May 1980, against the coup d''état of May Seventeenth by Chun Doo-hwan that strengthened his power. Chun had previously taken power and become military dictator through the coup d''état of December Twelfth at the end of 1979.', 1980, 5, 18, 1980, 5, 27, 'day', '18 May 1980 – 27 May 1980', 69, 'https://en.wikipedia.org/wiki/Gwangju_Uprising'),
  ('Q11233547', 'Korean Air Lines Flight 015', 'Korean Air Lines Flight 015 was a Boeing 747-200 operating a scheduled passenger flight from Los Angeles International Airport, in Los Angeles, California, to Gimpo International Airport in Seoul, South Korea with an intermediate stop in Anchorage, Alaska, that crashed while attempting to land on 19 November 1980. Of the 226 passengers and crew on board, 15 were killed in the accident.', 1980, 11, 19, NULL, NULL, NULL, 'day', '19 November 1980', 51, 'https://en.wikipedia.org/wiki/Korean_Air_Lines_Flight_015'),
  ('Q495953', 'Korean Air Flight 858', 'Korean Air Flight 858 was a scheduled international passenger flight between Baghdad, Iraq, and Seoul, South Korea. On 29 November 1987, the Boeing 707 flying the route exploded in mid-air upon the detonation of a bomb planted inside an overhead storage bin in the airplane''s passenger cabin by two North Korean agents.', 1987, 11, 29, NULL, NULL, NULL, 'day', '29 November 1987', 59, 'https://en.wikipedia.org/wiki/Korean_Air_Flight_858'),
  ('Q497194', 'June Struggle', 'The June Democratic Struggle (Korean: 6월 민주 항쟁), also known as the June Democracy Movement and the June Uprising, was a nationwide pro-democracy movement in South Korea that generated mass protests from 10 to 29 June 1987. The demonstrations forced the ruling authoritarian government to hold direct presidential elections and institute other democratic reforms, which led to the establishment of the Sixth Republic, the present-day government of the Republic of Korea (South Korea).', 1987, 6, 10, 1987, 6, 29, 'day', '10 June 1987 – 29 June 1987', 56, 'https://en.wikipedia.org/wiki/June_Democratic_Struggle'),
  ('Q497354', 'Asiana Airlines Flight 733', 'Asiana Airlines Flight 733 was a domestic Asiana Airlines passenger flight from Seoul-Gimpo International Airport to Mokpo Airport, South Korea. The Boeing 737-500 operating the flight crashed on 26 July 1993, in the Hwawon area of Haenam County, South Jeolla Province.', 1993, 7, 26, NULL, NULL, NULL, 'day', '26 July 1993', 53, 'https://en.wikipedia.org/wiki/Asiana_Airlines_Flight_733'),
  ('Q496032', '1996 Gangneung submarine infiltration incident', 'The 1996 Gangneung submarine infiltration incident began on 18 September 1996 near the South Korean city of Gangneung when North Koreans abandoned their grounded submarine and hid within the city, resulting in a 49-day manhunt for the belligerents. The incident was one of the more serious instances of North Korean espionage involving the Reconnaissance Bureau (reconnaissance team and 22nd Squadron of the Maritime Department of the Reconnaissance Bureau).', 1996, 9, 17, NULL, NULL, NULL, 'day', '17 September 1996', 43, 'https://en.wikipedia.org/wiki/1996_Gangneung_submarine_infiltration_incident'),
  ('Q16000825', '1998 Sokcho submarine incident', 'The 1998 Sokcho submarine incident occurred on 22 June 1998, offshore of the South Korean city of Sokcho.', 1998, 6, 22, NULL, NULL, NULL, 'day', '22 June 1998', 39, 'https://en.wikipedia.org/wiki/1998_Sokcho_submarine_incident'),
  ('Q47735', '2002 FIFA World Cup', 'The 2002 FIFA World Cup (Korean: 2002 FIFA 월드컵 한국/일본; Japanese: 2002 FIFAワールドカップ 韓国/日本) also branded as Korea Japan 2002, was the 17th FIFA World Cup, the quadrennial football world championship for men''s national teams organized by FIFA. It was held from 31 May to 30 June 2002 at sites in South Korea and Japan, with its final match hosted by Japan at International Stadium in Yokohama. A field of 32 teams qualified for this World Cup, which was the first to be held in Asia, the first to be held outside of the Americas or Europe, as well as the first to be hosted by more than one nation.', 2002, NULL, NULL, 2002, 6, 29, 'year', '2002', 87, 'https://en.wikipedia.org/wiki/2002_FIFA_World_Cup'),
  ('Q487565', 'Second Battle of Yeonpyeong', 'The Battle of Yeonpyeong, also known as the Second Battle of Yeonpyeong (South Korean: 제2연평해전; RR: Je I Yeonpyeong Haejeon), was a confrontation at sea between North Korean and South Korean patrol boats along a disputed maritime boundary near Yeonpyeong Island in the Yellow Sea in 2002. This followed a similar confrontation in 1999.', 2002, 6, 29, NULL, NULL, NULL, 'day', '29 June 2002', 50, 'https://en.wikipedia.org/wiki/Battle_of_Yeonpyeong_(2002)'),
  ('Q489904', 'Air China Flight 129', 'Air China Flight 129 (CCA129/CA129) was a scheduled international passenger flight, operated by Air China, from Beijing Capital International Airport to Gimhae International Airport in Busan. On 15 April 2002, the aircraft on this route, a Boeing 767, crashed into a hill named Mount Dotdae near Gimhae Airport, killing 129 of the 166 people on board.', 2002, 4, 15, NULL, NULL, NULL, 'day', '15 April 2002', 59, 'https://en.wikipedia.org/wiki/Air_China_Flight_129'),
  ('Q494058', 'ROKS Cheonan sinking', 'The Sinking of ROKS Cheonan occurred on 26 March 2010, when Cheonan, a Pohang-class corvette of South Korea, carrying 104 personnel, sank off the country''s west coast near Baengnyeong Island in the Yellow Sea, killing 46 seamen. The cause of the sinking is disputed.', 2010, 3, 26, NULL, NULL, NULL, 'day', '26 March 2010', 55, 'https://en.wikipedia.org/wiki/Sinking_of_ROKS_Cheonan'),
  ('Q16338015', 'sinking of the MV Sewol', 'On the morning of Wednesday, 16 April 2014, the ferry MV Sewol sank while en route from Incheon towards Jeju City in South Korea. The 6,825-ton vessel sent a distress signal from about 2.7 kilometres (1.7 mi; 1.5 nmi) north of Byeongpungdo at 08:58 KST (23:58 UTC, 15 April 2014).', 2014, 4, 16, NULL, NULL, NULL, 'day', '16 April 2014', 71, 'https://en.wikipedia.org/wiki/Sinking_of_MV_Sewol'),
  ('Q20024455', '2015 South Korea respiratory syndrome coronavirus outbreak', 'An outbreak of Middle East respiratory syndrome coronavirus occurred in South Korea from May 2015 to July 2015. The virus, which causes Middle East respiratory syndrome (MERS), was a newly emerged betacoronavirus that was first identified in a patient from Saudi Arabia in April 2012.', 2015, NULL, NULL, NULL, NULL, NULL, 'year', '2015', 45, 'https://en.wikipedia.org/wiki/2015_MERS_outbreak_in_South_Korea'),
  ('Q43170589', '2017 Pohang earthquake', 'The 2017 Pohang earthquake, measuring magnitude 5.4 on the local magnitude scale (5.5 Mw), struck Heunghae, Pohang, South Korea on November 15, 2017, and the hypocenter was 7 km below the surface. It is tied with the 2016 Gyeongju earthquake as the country''s strongest earthquake in modern history since seismological observations started in Korea in 1978, and the most destructive ever recorded with "an estimated 300 billion won (US$290 million) in damage.".', 2017, 11, 15, NULL, NULL, NULL, 'day', '15 November 2017', 45, 'https://en.wikipedia.org/wiki/2017_Pohang_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q113482445', '2022 Central Korean floods', 'On 8 August 2022, large scale floods hit the capital of South Korea, Seoul, especially affecting Gangnam District and its surrounding areas. It was preceded by the highest rainfall in 80 years.', 2022, 8, 8, NULL, NULL, NULL, 'day', '8 August 2022', 45, 'https://en.wikipedia.org/wiki/2022_South_Korea_floods'),
  ('Q120669170', '2023 South Korea floods', 'Heavy rainfall during the 2023 East Asian rainy season resulted in severe flooding and landslides across South Korea, primarily affecting residents in the provinces of North Chungcheong and North Gyeongsang. At least 47 people were killed and three are still missing as of 22 July 2023.', 2023, 6, 8, NULL, NULL, NULL, 'day', '8 June 2023', 51, 'https://en.wikipedia.org/wiki/2023_South_Korea_floods'),
  ('Q131581945', 'Jeju Air Flight 2216', 'Jeju Air Flight 2216 was a scheduled international passenger flight operated by Jeju Air from Suvarnabhumi Airport near Bangkok, Thailand, to Muan International Airport in Muan County, South Korea. On 29 December 2024, when the Boeing 737-800 operating the flight was approaching Muan, a bird strike occurred, with both of the engines ingesting birds, causing an apparent loss of thrust in the right engine.', 2024, 12, 29, NULL, NULL, NULL, 'day', '29 December 2024', 75, 'https://en.wikipedia.org/wiki/Jeju_Air_Flight_2216'),
  ('Q131930345', 'Air Busan Flight 391', 'Air Busan Flight 391 was a scheduled international passenger flight operated by Air Busan from Gimhae International Airport in Busan, South Korea, to Hong Kong International Airport in Hong Kong. On 28 January 2025, the Airbus A321 caught fire while preparing to taxi for takeoff.', 2025, 1, 28, NULL, NULL, NULL, 'day', '28 January 2025', 45, 'https://en.wikipedia.org/wiki/Air_Busan_Flight_391');
